 code=[dict(title="Data fit versus physics", lang="python", runnable=True, source="import numpy as np\nrng = np.random.default_rng(11)\ntruth = lambda t: np.exp(-0.3*t)*np.cos(2*t)\nphys = lambda t: np.exp(-0.45*t)*np.cos(1.85*t)   # physics model, slightly wrong parameters\nt_data = np.linspace(0, 2, 8)\ny_data = truth(t_data) + 0.05*rng.standard_normal(8)\ncoef = np.polyfit(t_data, y_data, 5)              # pure data model\nt_new = np.linspace(2.1, 6, 40)\nerr = lambda f: np.sqrt(np.mean((f(t_new) - truth(t_new))**2))\nprint(f'data fit error beyond the data: {err(lambda t: np.polyval(coef, t)):.2f}')\nprint(f'physics error beyond the data:  {err(phys):.2f}')",
   explain="A degree-5 polynomial fits 8 points well but explodes after t = 2; the slightly wrong physics model stays close.", expected="data fit error beyond the data: 259.02\nphysics error beyond the data:  0.13")],
 takeaways=["Physics extrapolates but misses details; data captures details but fails outside its range.", "Scientific machine learning combines physical laws with learning from data.", "Physical AI puts models into machines that sense and act in the real world.", "Transport is physics-rich but data-sparse where it matters most."],
